const tiers = (a: number, b: number, c: number) => [
  { id: 't1', name: 'Supporter', price: a, perks: ['Supporter badge', 'Supporters-only drops'] },
  { id: 't2', name: 'Inner circle', price: b, perks: ['Everything in Supporter', 'Monthly voice note', 'Early drops'] },
  { id: 't3', name: 'Patron', price: c, perks: ['Everything in Inner circle', 'Name in the credits', '1:1 call each quarter'] },
]

